package main

import (
	"context"
	"testing
)

func TestHistoryImportAdmissionReleaseAllowsNextImport(t *testing.T) {
	release, err := acquireHistoryHeavyBudget(context.Background(), "import-user", 1)
	if err != nil { t.Fatal(err) }
	release()
	release, err = acquireHistoryHeavyBudget(context.Background(), "import-user", 1)
	if err != nil { t.Fatal(err) }
	release()
}

func TestHistoryImportAdmissionTenantIsolation(t *testing.T) {
	one, err := acquireHistoryHeavyBudget(context.Background(), "tenant-a", 1)
	if err != nil { t.Fatal(err) }
	defer one()
	two, err := acquireHistoryHeavyBudget(context.Background(), "tenant-b", 1)
	if err != nil { t.Fatal(err) }
	two()
}
